17	// --- 扫描器本身：在解码后的成员名上判重 ---
18	
19	func TestFindDuplicateInvariantsFalseThenTrue(t *testing.T) {
20		data := []byte(`{"invariants":{"inv":false,"inv":true}}`)
21		dup := findDuplicateJSONMember(data)
22		if dup == nil {
23			t.Fatal("false then true for the same invariant must be detected")
24		}
25		if dup.member != "inv" {
26			t.Fatalf("duplicate member = %q, want inv", dup.member)
27		}
28	}
29	
30	func TestFindDuplicateRejectsEqualValues(t *testing.T) {
31		// 重复值相同也不放行：问题在于成员出现两次，而不是值冲突。
32		data := []byte(`{"invariants":{"inv":true,"inv":true}}`)
33		if findDuplicateJSONMember(data) == nil {
34			t.Fatal("identical repeated values must still be a duplicate")
35		}
36	}
