452		if err == nil {
453			t.Fatalf("expected rejection, got %+v", loaded)
454		}
455		if !reflect.DeepEqual(loaded, Report{}) {
456			t.Fatalf("failed read must return the zero report, got %+v", loaded)
457		}
458	}
459	
460	func TestLoadReportDoesNotDeleteOrRepairCorruptArchive(t *testing.T) {
461		dir := t.TempDir()
462		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
463			stored.Findings = append(stored.Findings, stored.Findings[0])
464		})
465		path := filepath.Join(dir, id+".json")
466		before, err := os.ReadFile(path)
467		if err != nil {
468			t.Fatal(err)
469		}
470		for i := 0; i < 2; i++ {
471			if _, err := LoadReport(dir, id); err == nil {
472				t.Fatal("expected corrupt rejection on repeated reads")
473			}
474		}
475		after, err := os.ReadFile(path)
476		if err != nil {
477			t.Fatalf("corrupt archive must not be deleted: %v", err)
478		}
479		if string(after) != string(before) {
480			t.Fatal("failed read must not rewrite or repair the archive")
481		}
482	}
483	
484	// 成功读取同样不得改写归档。
485	func TestLoadReportSuccessDoesNotModifyArchive(t *testing.T) {
486		dir := t.TempDir()
487		id := writeReportWithFreshID(t, dir, oneDefectFixture())
488		path := filepath.Join(dir, id+".json")
489		before, err := os.ReadFile(path)
490		if err != nil {
491			t.Fatal(err)
492		}
493		if _, err := LoadReport(dir, id); err != nil {
494			t.Fatal(err)
495		}
496		after, err := os.ReadFile(path)
497		if err != nil {
498			t.Fatal(err)
499		}
500		if string(after) != string(before) {
501			t.Fatal("successful read must not rewrite the archive")
502		}
503	}
504	
505	// 损坏拒绝不得创建任何额外的存储文件（读取路径只读）。
506	func TestLoadReportFailureCreatesNoFiles(t *testing.T) {
507		dir := t.TempDir()
508		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
509			stored.Findings[0].Invariant = "other-inv"
510		})
511		before, err := os.ReadDir(dir)
512		if err != nil {
513			t.Fatal(err)
514		}
515		if _, err := LoadReport(dir, id); err == nil {
516			t.Fatal("expected corrupt rejection")
517		}
518		after, err := os.ReadDir(dir)
519		if err != nil {
520			t.Fatal(err)
521		}
522		if len(after) != len(before) {
523			t.Fatalf("failed read changed file count: %d -> %d", len(before), len(after))
524		}
525	}
526	
527	// --- 错误三分类：损坏 ≠ 不存在 ≠ 请求标识不合法 ---
528	
529	func TestLoadReportErrorClassificationDistinct(t *testing.T) {
530		dir := t.TempDir()
531	
532		// 1) 损坏归档
533		corruptID := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
534			stored.Findings = nil
535		})
536		if _, err := LoadReport(dir, corruptID); err == nil {
537			t.Fatal("expected corrupt error")
