15	
16	// 本文件在真实命令行进程边界上回归保护 diff 命令：用户指定基准报告与新报告
17	// 后，命令必须输出可解析的完整比较 JSON，并严格保持分类口径——只有
18	// 通过→发现缺陷 才是“新发现缺陷”，反向才是“已消除缺陷”；未检查、工具缺失、
19	// 超时都不能证明合约安全或缺陷已修复。任一报告读取失败时必须非零退出、
20	// 原因进 stderr、stdout 不出现任何局部结果，且比较全程不改动归档。
21	
22	// diffRules 是前后两份报告共用的同一批规则定义（id、kind、severity、
23	// invariant、ABI 要求、版本完全一致），只有这样两侧状态才允许直接比较。
24	func diffRules() []cliWireRule {
25		return []cliWireRule{
26			{ID: "a-resolved", Kind: "static", Severity: "high", Invariant: "inv-resolved", Version: "1"},
27			{ID: "b-tool-to-pass", Kind: "static", Severity: "medium", Invariant: "inv-tool", RequiresABI: true, Version: "2"},
28			{ID: "c-unchecked-to-pass", Kind: "static", Severity: "info", Invariant: "inv-unchecked", Version: "3"},
29			{ID: "d-stable-defect", Kind: "static", Severity: "high", Invariant: "inv-stable-def", Version: "4"},
30			{ID: "e-stable-pass", Kind: "static", Severity: "low", Invariant: "inv-stable-pass", Version: "5"},
31			{ID: "f-note-change", Kind: "static", Severity: "low", Invariant: "inv-note", Version: "6"},
32			{ID: "m-timeout-to-defect", Kind: "symbolic", Severity: "critical", Invariant: "inv-td", Version: "7"},
33			{ID: "n-defect-to-timeout", Kind: "symbolic", Severity: "critical", Invariant: "inv-dt", Version: "8"},
34			{ID: "z-new-defect", Kind: "static", Severity: "high", Invariant: "inv-new", Version: "9"},
35		}
36	}
37	
38	// 基准侧缺陷证据同样刻意保留中文、换行与前后空格。
39	const resolvedEvidence = "  旧缺陷：重入路径仍可达\n第二行证据  "
40	
41	// diffBeforeChecks/diffAfterChecks 覆盖所有关键状态迁移。
42	// 基准侧：a/d/n 三条缺陷（共 3 个真实缺陷）；新侧：d/m/z 三条缺陷（共 3 个）。
43	func diffBeforeChecks(hash string) []cliWireCheck {
44		return []cliWireCheck{
45			{ArtifactHash: hash, RuleID: "z-new-defect", Version: "9", Status: contractsentinel.StatusPass},
46			{ArtifactHash: hash, RuleID: "a-resolved", Version: "1", Status: contractsentinel.StatusDefect, Note: resolvedEvidence},
47			{ArtifactHash: hash, RuleID: "m-timeout-to-defect", Version: "7", Status: contractsentinel.StatusTimeout, Note: "超过 60s 截止时间"},
48			{ArtifactHash: hash, RuleID: "n-defect-to-timeout", Version: "8", Status: contractsentinel.StatusDefect, Note: "超时前发现的反例"},
49			{ArtifactHash: hash, RuleID: "b-tool-to-pass", Version: "2", Status: contractsentinel.StatusToolMissing, Note: "符号执行引擎未安装"},
50			// c-unchecked-to-pass 在基准侧刻意没有记录：应为未检查。
51			{ArtifactHash: hash, RuleID: "d-stable-defect", Version: "4", Status: contractsentinel.StatusDefect, Note: "稳定缺陷证据"},
52			{ArtifactHash: hash, RuleID: "e-stable-pass", Version: "5", Status: contractsentinel.StatusPass},
53			{ArtifactHash: hash, RuleID: "f-note-change", Version: "6", Status: contractsentinel.StatusPass, Note: "旧说明"},
54		}
55	}
56	
57	func diffAfterChecks(hash string) []cliWireCheck {
58		return []cliWireCheck{
59			{ArtifactHash: hash, RuleID: "f-note-change", Version: "6", Status: contractsentinel.StatusPass, Note: "新说明"},
60			{ArtifactHash: hash, RuleID: "z-new-defect", Version: "9", Status: contractsentinel.StatusDefect, Note: defectNote},
61			{ArtifactHash: hash, RuleID: "a-resolved", Version: "1", Status: contractsentinel.StatusPass},
