489			after  string
490		}{
491			{"second report corrupt", good.ReportID, bad.ReportID},
492			{"first report corrupt", bad.ReportID, good.ReportID},
493		}
494		for _, tc := range cases {
495			t.Run(tc.name, func(t *testing.T) {
496				stdout, stderr, code := runCLIDiff(t, bin, store, tc.before, tc.after)
497				if code == 0 {
498					t.Fatal("diff must exit non-zero for a corrupted archive")
499				}
500				if !strings.Contains(stderr, "invalid JSON") {
501					t.Fatalf("stderr must describe the corrupted archive:\n%s", stderr)
502				}
503				if stdout != "" {
504					t.Fatalf("stdout must be empty on failure, got:\n%s", stdout)
505				}
506				for _, marker := range []string{good.ReportID, bad.ReportID, `"results"`, `"summary"`,
507					contractsentinel.ChangeNewDefect, contractsentinel.ChangeResolvedDefect,
508					contractsentinel.StatusUnchecked, contractsentinel.StatusDefect} {
509					if strings.Contains(stdout, marker) {
510						t.Fatalf("stdout must not leak %q on failure:\n%s", marker, stdout)
511					}
512				}
513			})
514		}
515	}
516	
517	// 比较只是读取操作：成功与失败都必须保持归档原样——不补写报告、不修复
518	// 损坏内容、不留下临时文件。
519	func TestCLIDiffNeverModifiesStore(t *testing.T) {
520		bin := auditBinary(t)
521		work := t.TempDir()
522		store := filepath.Join(work, "reports")
523		artifact := mixedCheckArtifact()
524		hash := mixedArtifactHash(t)
525		rules := diffRules()
526		before := auditDiffReport(t, bin, work, store, "before.json", artifact, rules, diffBeforeChecks(hash))
527		after := auditDiffReport(t, bin, work, store, "after.json", artifact, rules, diffAfterChecks(hash))
528	
529		snapshot := func(t *testing.T) map[string]string {
530			t.Helper()
531			names, err := listFiles(store)
532			if err != nil {
533				t.Fatal(err)
534			}
535			sort.Strings(names)
536			out := map[string]string{}
537			for _, name := range names {
538				data, err := os.ReadFile(filepath.Join(store, name))
539				if err != nil {
540					t.Fatal(err)
541				}
542				out[name] = string(data)
543			}
544			return out
545		}
546		gotKeys := func(m map[string]string) []string {
547			keys := make([]string, 0, len(m))
548			for k := range m {
549				keys = append(keys, k)
550			}
551			sort.Strings(keys)
552			return keys
553		}
554		sameSnapshot := func(t *testing.T, got, want map[string]string) {
555			t.Helper()
556			if len(got) != len(want) {
557				t.Fatalf("store file set changed: %v vs %v", gotKeys(got), gotKeys(want))
558			}
559			for name, data := range want {
560				if got[name] != data {
561					t.Errorf("archive %s modified by diff", name)
562				}
563			}
564		}
565	
566		original := snapshot(t)
567	
568		// 成功的比较不得改动任何归档。
569		if _, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID); code != 0 {
570			t.Fatalf("successful diff failed: %s", stderr)
571		}
572		sameSnapshot(t, snapshot(t), original)
573	
574		// 损坏第二份归档后，失败的比较既不修复它，也不碰其他归档。
575		badPath := filepath.Join(store, after.ReportID+".json")
576		corrupt := []byte(`{"reportId":"corrupt"}`)
577		if err := os.WriteFile(badPath, corrupt, 0o644); err != nil {
578			t.Fatal(err)
579		}
580		if _, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID); code == 0 {
581			t.Fatalf("diff against corrupted archive must fail: %s", stderr)
582		}
583		names, err := listFiles(store)
584		if err != nil {
585			t.Fatal(err)
586		}
587		if len(names) != len(original) {
588			t.Fatalf("failure changed the store file set: %v", names)
589		}
590		kept, err := os.ReadFile(badPath)
